 const hasCombined=!!db.documents.find(d=>d.type==='Proforma'&&d.rootId===q.id&&d.status!=='Cancelled'&&d.serviceIndex===undefined),requestedMode=requestedBillingMode==='service-completion'?'service-wise':requestedBillingMode,billingMode=hasCombined?'project':requestedMode||'service-wise';
